components.onTick:
const R = state.cells.length, C = state.cells[0].length, dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
const look = (r, c, fr, fc) => (r < 0 || c < 0 || r >= R || c >= C || state.cells[r][c] === 1) ? state.V[fr][fc] : state.V[r][c];
const V = state.cells.map((row, r) => row.map((t, c) => t === 1 ? 0 : t === 2 ? 1 : t === 3 ? -1 : round(-0.04 + state.gamma * maxOf(dirs.map(([dr, dc]) => look(r + dr, c + dc, r, c))), 3)));
const delta = maxOf(V.flat().map((v, i) => Math.abs(v - state.V.flat()[i])));
if (delta < 1e-3) return null;
return { V, iter: state.iter + 1 };

components.draw:
const R = state.cells.length, C = state.cells[0].length, dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]], names = ['up', 'down', 'left', 'right'];
const ok = (r, c) => r >= 0 && c >= 0 && r < R && c < C && state.cells[r][c] !== 1;
const arrows = state.cells.map((row, r) => row.map((t, c) => t ? null : names[argmax(dirs.map(([dr, dc]) => ok(r + dr, c + dc) ? state.V[r + dr][c + dc] : -9))]));
return [grid(state.cells, { id: 'world', labels: state.V.map((row, r) => row.map((v, c) => state.cells[r][c] === 1 ? '' : round(v, 2))), ...(state.iter ? { arrows } : {}), agents: [{ r: state.start[0], c: state.start[1] }], draggable: true })];

components.onClick:
if (part !== 'cell') return null;
const C = state.cells[0].length, r = Math.floor(index / C), c = index % C;
if (state.cells[r][c] > 1 || (r === state.start[0] && c === state.start[1])) return null;
return { cells: state.cells.map((row, i) => row.map((v, j) => i === r && j === c ? 1 - v : v)), V: state.cells.map((row) => row.map(() => 0)), iter: 0 };
